import pandas as pd
import pytest
from pyam import IamDataFrame

from nomenclature.processor.data_validator import DataValidator


def make_df():
    return IamDataFrame(
        pd.DataFrame(
            [
                ["m", "s", "World", "Primary Energy", "EJ/yr", 1.0, 6.0],
                ["m", "s", "World", "Emissions|CO2", "Mt CO2/yr", 10.0, 20.0],
            ],
            columns=[
                "model", "scenario", "region", "variable", "unit", 2005, 2010,
            ],
        )
    )


def run(tmp_path, text):
    f = tmp_path / "v.yaml"
    f.write_text(text)
    return DataValidator.from_file(f).apply(make_df())


