import pytest

from flowpipe.node import Node
from flowpipe.plug import SubOutputPlug, OutputPlug


def make(outputs):
    @Node(outputs=outputs)
    def MyNode():
        pass
    return MyNode(graph=None)


def test_sub_plugs_created():
    node = make(["out.a", "out.b"])
    assert isinstance(node.outputs["out"], OutputPlug)
    assert isinstance(node.outputs["out"]["a"], SubOutputPlug)
    assert isinstance(node.outputs["out"]["b"], SubOutputPlug)


def test_no_dotted_top_level_keys():
    node = make(["out.a", "out.b"])
    assert list(node.outputs.keys()) == ["out"]


def test_parent_declared_explicitly_with_subs():
    node = make(["out", "out.a", "other"])
    assert set(node.outputs.keys()) == {"out", "other"}
    assert isinstance(node.outputs["out"]["a"], SubOutputPlug)


def test_parent_declared_after_sub():
    node = make(["out.a", "out"])
    assert list(node.outputs.keys()) == ["out"]
    assert isinstance(node.outputs["out"]["a"], SubOutputPlug)


def test_plain_outputs_unchanged():
    node = make(["x", "y"])
    assert set(node.outputs.keys()) == {"x", "y"}
    assert not isinstance(node.outputs["x"], SubOutputPlug)


def test_sub_plug_connects_and_passes_value():
    up = make(["out.a", "out.b"])
    down = make(["res"])
    from flowpipe.plug import InputPlug
    inp = InputPlug("in", down)
    up.outputs["out"]["a"].value = 3
    up.outputs["out"]["b"].value = 4
    up.outputs["out"]["a"] >> inp
    assert inp.value == 3
    assert up.outputs["out"]["b"].value == 4

