from pybv.io import write_brainvision

MU_MICRO = "\u00b5"
MU_GREEK = "\u03bc"


def _write(tmp_path, unit, name="t"):
    data = np.random.RandomState(0).randn(2, 50) * 1e-5
    write_brainvision(data, 1000., ['a', 'b'], name, str(tmp_path), unit=unit)
    with open(os.path.join(str(tmp_path), name + '.vhdr'), encoding='utf-8') as f:
        return f.read()


def test_greek_mu_accepted_and_normalized(tmp_path):
    text = _write(tmp_path, MU_GREEK + "V")
    assert MU_MICRO + "V" in text
    assert MU_GREEK not in text


def test_micro_sign_accepted(tmp_path):
    text = _write(tmp_path, MU_MICRO + "V")
    assert MU_MICRO + "V" in text


def test_u_alias_becomes_micro(tmp_path):
    text = _write(tmp_path, "uV")
    assert MU_MICRO + "V" in text


@pytest.mark.parametrize("unit", ["V", "mV", "nV", None])
def test_other_valid_units(tmp_path, unit):
    _write(tmp_path, unit)


@pytest.mark.parametrize("unit", ["sV", "kV", "xyz", "", "Vu"])
def test_invalid_units_raise_valueerror(tmp_path, unit):
    with pytest.raises(ValueError):
        _write(tmp_path, unit)

