import ast
import os

import pytest

ROOT = os.getcwd()


def _py_files(sub):
  base = os.path.join(ROOT, sub)
  out = []
  for d, _, files in os.walk(base):
    for f in files:
      if f.endswith('.py'):
        out.append(os.path.join(d, f))
  return sorted(out)


def _ann_text(node):
  if isinstance(node, ast.Constant) and isinstance(node.value, str):
    return node.value
  return ast.unparse(node) if hasattr(ast, 'unparse') else ast.dump(node)


def _params(tree):
  for fn in ast.walk(tree):
    if not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):
      continue
    a = fn.args
    pos = a.posonlyargs + a.args
    defaults = [None] * (len(pos) - len(a.defaults)) + list(a.defaults)
    for arg, d in zip(pos, defaults):
      yield fn, arg, d
    for arg, d in zip(a.kwonlyargs, a.kw_defaults):
      yield fn, arg, d


def _is_none(d):
  return isinstance(d, ast.Constant) and d.value is None


def _is_optional(text):
  t = text.replace(' ', '')
  return ('Optional[' in t or 'Union[' in t and 'None' in t or
          '|None' in t or t in ('Any', 'typing.Any', 'None'))


def _violations_none(sub):
  bad = []
  for path in _py_files(sub):
    with open(path, encoding='utf-8') as f:
      tree = ast.parse(f.read())
    for fn, arg, d in _params(tree):
      if d is not None and _is_none(d) and arg.annotation is not None:
        if not _is_optional(_ann_text(arg.annotation)):
          bad.append('{0}:{1} {2}.{3}'.format(
              os.path.relpath(path, ROOT), fn.lineno, fn.name, arg.arg))
  return bad


def _violations_nonnone(sub):
  bad = []
  for path in _py_files(sub):
    with open(path, encoding='utf-8') as f:
      tree = ast.parse(f.read())
    for fn, arg, d in _params(tree):
      if d is not None and not _is_none(d) and arg.annotation is not None:
        t = _ann_text(arg.annotation).replace(' ', '')
        if t.startswith('Optional[') or t.startswith('typing.Optional['):
          bad.append('{0}:{1} {2}.{3}'.format(
              os.path.relpath(path, ROOT), fn.lineno, fn.name, arg.arg))
  return bad


def test_scan_finds_optional_params():
  count = 0
  for path in _py_files('libcloudforensics'):
    with open(path, encoding='utf-8') as f:
      tree = ast.parse(f.read())
    for _, arg, d in _params(tree):
      if d is not None and _is_none(d):
        count += 1
  assert count > 10


def test_none_default_is_optional_in_library():
  assert _violations_none('libcloudforensics') == []


def test_none_default_is_optional_in_examples():
  if not os.path.isdir(os.path.join(ROOT, 'examples')):
    pytest.skip('no examples')
  assert _violations_none('examples') == []


def test_no_optional_with_non_none_default_in_library():
  assert _violations_nonnone('libcloudforensics') == []


def test_no_optional_with_non_none_default_in_examples():
  if not os.path.isdir(os.path.join(ROOT, 'examples')):
    pytest.skip('no examples')
  assert _violations_nonnone('examples') == []

