import unittest
from typing import Optional, Union, List

from overrides import overrides
from overrides.enforce import ensure_signature_is_compatible


class TestFutureAnnotations(unittest.TestCase):
    def test_same_types_ok(self):
        class A:
            def f(self, x: int, y: str) -> int:
                return 1

        class B(A):
            def f(self, x: int, y: str) -> int:
                return 2

        ensure_signature_is_compatible(A.f, B.f)

    def test_param_type_mismatch_raises(self):
        class A:
            def f(self, x: int) -> int:
                return 1

        class B(A):
            def f(self, x: str) -> int:
                return 2

        with self.assertRaises(TypeError):
            ensure_signature_is_compatible(A.f, B.f)

    def test_param_contravariance(self):
        class A:
            def f(self, x: int) -> int:
                return 1

        class B(A):
            def f(self, x: Union[int, str]) -> int:
                return 2

        class C(A):
            def f(self, x: int) -> int:
                return 2

        ensure_signature_is_compatible(A.f, B.f)

        class D:
            def f(self, x: Union[int, str]) -> int:
                return 1

        class E(D):
            def f(self, x: int) -> int:
                return 2

        with self.assertRaises(TypeError):
            ensure_signature_is_compatible(D.f, E.f)

    def test_return_covariance(self):
        class A:
            def f(self) -> Union[int, str]:
                return 1

        class B(A):
            def f(self) -> int:
                return 2

        ensure_signature_is_compatible(A.f, B.f)

        class C:
            def f(self) -> int:
                return 1

        class D(C):
            def f(self) -> Optional[int]:
                return 2

        with self.assertRaises(TypeError):
            ensure_signature_is_compatible(C.f, D.f)

    def test_return_mismatch_raises(self):
        class A:
            def f(self) -> List[int]:
                return []

        class B(A):
            def f(self) -> str:
                return ""

        with self.assertRaises(TypeError):
            ensure_signature_is_compatible(A.f, B.f)

    def test_overrides_decorator(self):
        class A:
            def f(self, x: int) -> int:
                return 1

        class B(A):
            @overrides
            def f(self, x: int) -> int:
                return 2

        self.assertEqual(B().f(1), 2)

        with self.assertRaises(TypeError):

            class C(A):
                @overrides
                def f(self, x: str) -> int:
                    return 2

            ensure_signature_is_compatible(A.f, C.f)

