from packaging.version import Version

from fromager.settings import Settings


def test_no_changelog_gives_empty_build_tag():
    settings = Settings({"packages": {"foo": {"build_dir": "build"}}})
    assert settings.build_tag("foo", Version("1.0")) == ()
    assert settings.build_tag("foo", "1.0") == ()


def test_package_changelog_only_still_works():
    settings = Settings(
        {"packages": {"foo": {"changelog": {"1.0": ["change one", "change two"]}}}}
    )
    assert settings.build_tag("foo", Version("1.0")) == (2, "")


def test_global_changelog_applies_to_every_package():
    settings = Settings({"changelog": {"1.0": ["global change"]}})
    assert settings.build_tag("foo", Version("1.0")) == (1, "")
    assert settings.build_tag("bar", Version("1.0")) == (1, "")


def test_global_changelog_applies_even_when_package_has_other_settings():
    settings = Settings(
        {
            "changelog": {"1.0": ["g1", "g2"]},
            "packages": {"foo": {"build_dir": "build"}},
        }
    )
    assert settings.build_tag("foo", Version("1.0")) == (2, "")


def test_global_and_package_changelog_entries_combine():
    settings = Settings(
        {
            "changelog": {"1.0": ["g1", "g2"]},
            "packages": {"foo": {"changelog": {"1.0": ["p1", "p2", "p3"]}}},
        }
    )
    assert settings.build_tag("foo", Version("1.0")) == (5, "")


def test_changelog_is_version_specific():
    settings = Settings(
        {
            "changelog": {"1.0": ["g1"]},
            "packages": {"foo": {"changelog": {"1.0": ["p1"]}}},
        }
    )
    assert settings.build_tag("foo", Version("2.0")) == ()
    assert settings.build_tag("foo", "2.0") == ()

