import lizard


def names(code):
    info = lizard.analyze_file.analyze_source_code("a.swift", code)
    return [f.name for f in info.function_list]


ENUM = '''
public enum HTTPMethod: String {
    case options = "OPTIONS"
    case get     = "GET"
    case head    = "HEAD"
}
'''


def test_enum_case_get_not_function():
    assert "get" not in names(ENUM)
    assert names(ENUM) == []


def test_functions_after_enum_found_separately():
    code = ENUM + '''
extension A {
    func foo(_ a: Int) {
        if a > 1 { return }
    }
    func bar(_ b: Int) {
    }
}
'''
    assert names(code) == ["foo", "bar"]
    info = lizard.analyze_file.analyze_source_code("a.swift", code)
    by = {f.name: f for f in info.function_list}
    assert by["foo"].cyclomatic_complexity == 2
    assert by["bar"].cyclomatic_complexity == 1


def test_variable_named_get_and_set():
    code = '''
func f() {
    let get = 1
    var set = 2
}
func g() {
}
'''
    assert names(code) == ["f", "g"]


def test_real_getter_still_detected():
    code = '''
class A {
    var x: Int {
        get {
            return 1
        }
    }
}
'''
    assert "get" in names(code)


def test_init_still_detected_after_enum():
    code = ENUM + '''
class B {
    init(a: Int) {
        self.a = a
    }
}
'''
    assert names(code) == ["init"]

