import pytest
from sqlglot import parse_one, transpile


def rt(sql):
    return parse_one(sql, dialect="mysql").sql(dialect="mysql")


def test_issue_example_roundtrip():
    sql = "CREATE TABLE `foo` (a VARCHAR(10), KEY idx_a (a DESC))"
    assert rt(sql) == sql


def test_asc_roundtrip():
    sql = "CREATE TABLE foo (a INT, KEY idx_a (a ASC))"
    assert rt(sql) == sql


def test_composite_mixed():
    sql = "CREATE TABLE foo (a INT, b INT, c INT, KEY idx_abc (a, b DESC, c ASC))"
    assert rt(sql) == sql


def test_composite_no_direction_unchanged():
    sql = "CREATE TABLE foo (a INT, b INT, KEY idx_ab (a, b))"
    assert rt(sql) == sql


def test_unique_key_desc_first_column():
    sql = "CREATE TABLE foo (a INT, b INT, UNIQUE KEY idx_ab (a DESC, b))"
    assert rt(sql) == sql


def test_no_alias_in_ast():
    ast = parse_one("CREATE TABLE foo (a INT, KEY idx_a (a DESC))", dialect="mysql")
    from sqlglot import exp

    assert not list(ast.find_all(exp.Alias))
    assert transpile("CREATE TABLE foo (a INT, KEY idx_a (a DESC))", read="mysql", write="mysql")[0] == (
        "CREATE TABLE foo (a INT, KEY idx_a (a DESC))"
    )
